pub fn coefficients<T:Copy>(self, rows: &[T;1024]) -> [T;1024] {
        core::array::from_fn(|j|rows[self.row(j)])
    }

pub fn new(variant:Variant,alpha:&[K;10],z:&[SecureCirclePoint;2])->Result<Box<Self>,Error> {
        let mut out=aspis_core::r0::heap::uninit::<Self>().map_err(|_|Error::Allocation)?;
        unsafe {
            let p=out.as_mut_ptr();
            core::ptr::addr_of_mut!((*p).variant).write(variant);
            core::ptr::addr_of_mut!((*p).points).write(aspis_core::state_only_prefix::r0::statement_points(alpha));
            core::ptr::addr_of_mut!((*p).extra).write([alpha[8],alpha[9]]);
            for k in 0..3 { for d in 0..5 {
                let a=(*p).points[k][9-2*TAU[d]]; let b=(*p).points[k][8-2*TAU[d]];
                (*p).factors[k][d]=[K::ONE.sub(a).mul(K::ONE.sub(b)),a.mul(K::ONE.sub(b)),K::ONE.sub(a).mul(b),a.mul(b)];
            }}
            for k in 0..2 {
                (*p).factors[3+k][0]=[K::ONE,z[k].y,z[k].x,z[k].x.mul(z[k].y)];
                let mut x=double(z[k].x);
                for d in 1..5 {
                    let y=double(x); (*p).factors[3+k][d]=[K::ONE,x,y,x.mul(y)]; x=double(y);
                }
            }
            Ok(out.assume_init())
        }
    }

pub fn materialize(&self,kappa:E)->Result<Vec<E>,Error> {
        let kp=powers::<7>(kappa);
        let mut w=aspis_core::r0::heap::filled(1024,E::ZERO).map_err(|_|Error::Allocation)?;
        for (j,v) in w.iter_mut().enumerate() {for kind in 0..7 {*v=v.add(kp[kind].mul_qm31(self.raw(kind,j)));}}
        Ok(w)
    }

pub(crate) fn map<T:Send,F:Fn(usize)->T+Sync>(_stage:usize,n:usize,f:F)->Vec<T> {
    let chunks=pool::ordered_families(pool::THREADS,|k| {
        let (a,b)=pool::range(n,k);
        let mut out=Vec::with_capacity(b-a);
        let mut completed=0;
        for i in a..b {out.push(f(i));completed+=1;}
        (out,completed)
    });
    let mut out=Vec::with_capacity(n);
    for (k,(mut chunk,completed)) in chunks.into_iter().enumerate() {
        #[cfg(feature="public-work-trace")]
        {let (a,b)=pool::range(n,k);TRACE.lock().unwrap().push([_stage,n,k,a,b,completed]);}
        #[cfg(not(feature="public-work-trace"))]
        let _=(k,completed);
        out.append(&mut chunk);
    }
    out
}

pub fn circle_sample(block: &[u8; 32], row: CircleRow) -> SecureCirclePoint {
    secure_ood_circle_point_from_parameter(qm31_sample(block)).unwrap_or_else(|_| {
        aspis_core::transcript::circle_fallback_point(match row {
            CircleRow::First => 0,
            CircleRow::Second => 1,
        })
    })
}

pub fn gamma_sample(block: &[u8; 32]) -> WideExact {
    let (mut digits, quotient) = low_base_p_digits(block);
    let wrapped = add_small_base_p(&mut digits, quotient + 1);
    if wrapped {
        let wrapped_again = add_small_base_p(&mut digits, 1);
        debug_assert!(!wrapped_again);
    }
    decode8(digits)
}

pub fn ordinary_sample(block: &[u8; 32]) -> WideExact {
    let (digits, _) = low_base_p_digits(block);
    decode8(digits)
}

pub fn value(tag: u16, index: usize, x: E) {
    #[cfg(all(feature="prover", not(feature="ct-host-prover")))]
    VALUES.with(|v| v.borrow_mut().push((tag,index,x.to_le_bytes())));
    #[cfg(any(not(feature="prover"), feature="ct-host-prover"))]
    let _ = (tag,index,x);
}

pub fn powers<const N:usize>(x:E)->[E;N]{
 let mut out=[E::ZERO;N];
 let mut p=E::ONE;
 let mut i=0usize;
 while i<N {
  out[i]=p;
  i+=1;
  if i==N { return out; }
  p=p.mul(x);
 }
 out
}

pub fn raw(&self,kind:usize,j:usize)->K {
        match kind {
            0=>if aspis_core::r0::opening::inactive(self.variant.row(j)).unwrap() {K::ONE} else {K::ZERO},
            4=>if j<56 { self.extra[j/28].pow((j%28) as u64) } else {K::ZERO},
            1..=3 if self.variant==Variant::D => {
                let r=self.variant.row(j);
                (0..10).fold(K::ONE,|v,b|v.mul(if r&(1<<b)==0 {K::ONE.sub(self.points[kind-1][9-b])}else{self.points[kind-1][9-b]}))
            },
            _=> {
                let k=if kind<4 {kind-1}else{kind-2};
                (0..5).fold(K::ONE,|v,d|v.mul(self.factors[k][d][(j>>(2*d))&3]))
            }
        }
    }

pub fn qm31_sample(block: &[u8; 32]) -> QM31 {
    let digits = qm31_digits(block);
    QM31 {
        c0: CM31::new(M31(digits[0]), M31(digits[1])),
        c1: CM31::new(M31(digits[2]), M31(digits[3])),
    }
}

pub(crate) fn all_slots_clear(values: &[[[QM31; 2]; 2]], masks: &[u16; 64], chi: QM31) -> bool {
    let mut clear = true;
    for (row, sides) in values.iter().enumerate() {
        let active = masks[row >> 4] & (1 << (row & 15)) != 0;
        for side in sides {
            for value in side {
                clear = keep_clear(clear, active, chi, *value);
            }
        }
    }
    clear
}

pub fn binary_parent<H: Digest32>(hash: H, left: &[u8; 32], right: &[u8; 32]) -> [u8; 32] {
    hash.digest(&[&[BINARY_NODE_TAG], left, right])
}
